const readJson = (key,fallback) => { try { const val=JSON.parse(localStorage.getItem(key)); return val ?? fallback; } catch { return fallback; } };
const makeId = () => Math.random().toString(36).slice(2,9);
const inTauri = () => typeof window !== "undefined" && !!window.__TAURI__?.core?.invoke;
async function callNative(command,args={}) { if (!inTauri()) throw new Error("Запустите SYNAPS как приложение Tauri, чтобы подключиться к локальному движку."); return window.__TAURI__.core.invoke(command,args); }
async function streamNative(args,onEvent){if(!inTauri())throw new Error("Streaming доступен только в desktop runtime.");const Channel=window.__TAURI__?.core?.Channel;if(!Channel)throw new Error("Tauri Channel API недоступен в этой сборке.");const channel=new Channel();channel.onmessage=onEvent;return window.__TAURI__.core.invoke("stream_completion",{...args,onEvent:channel});}

export default function App(){
 const [settings,setSettings]=useState(()=>({...DEFAULT,...readJson("synaps-settings",{})}));
 const [nodes,setNodes]=useState(()=>readJson("synaps-nodes",SEED_NODES));
 const [edges,setEdges]=useState(()=>readJson("synaps-edges",SEED_EDGES));
 const [skills,setSkills]=useState(()=>readJson("synaps-skills",[])); const [customNodes,setCustomNodes]=useState(()=>readJson("synaps-custom-nodes",[]));
 const [view,setView]=useState("Workspace"); const [selected,setSelected]=useState("model");
 const [runState,setRunState]=useState("ready"); const [trace,setTrace]=useState([]); const [result,setResult]=useState(""); const [metrics,setMetrics]=useState(null); const requestRef=useRef(null); const cancelRef=useRef(false);
 const [models,setModels]=useState([]); const [loadingModels,setLoadingModels]=useState(false); const [llamaStatus,setLlamaStatus]=useState({running:false}); const [llamaLogs,setLlamaLogs]=useState(""); const [status,setStatus]=useState(""); const [query,setQuery]=useState("");
 const [connectFrom,setConnectFrom]=useState(null); const [showContext,setShowContext]=useState(true); const [drag,setDrag]=useState(null); const [experiments,setExperiments]=useState(()=>readJson("synaps-experiments",[])); const [projectVersions,setProjectVersions]=useState([]); const [activeNode,setActiveNode]=useState(null);
 const [newSkill,setNewSkill]=useState({name:"",description:"",instructions:"",version:"1.0.0"}); const [skillModal,setSkillModal]=useState(false); const [customModal,setCustomModal]=useState(false); const [nodeDraft,setNodeDraft]=useState({name:"",description:"",category:"PROCESSING",version:"1.0.0",inputType:"text",outputType:"text",documentation:""});
 const chosen=nodes.find(n=>n.id===selected); const palette=settings.theme==="custom"?{accent:settings.customAccent||"#e1c43a",signal:"#71cfae"}:(PALETTES[settings.theme]||PALETTES.amber);
 useEffect(()=>{localStorage.setItem("synaps-settings",JSON.stringify(settings));document.documentElement.style.setProperty("--accent",palette.accent);document.documentElement.style.setProperty("--signal",palette.signal);document.documentElement.style.setProperty("--ui-font",settings.font+", Segoe UI, sans-serif");},[settings,palette]);
 useEffect(()=>{localStorage.setItem("synaps-nodes",JSON.stringify(nodes));localStorage.setItem("synaps-edges",JSON.stringify(edges));},[nodes,edges]);
 useEffect(()=>{localStorage.setItem("synaps-skills",JSON.stringify(skills));},[skills]);
 useEffect(()=>{localStorage.setItem("synaps-custom-nodes",JSON.stringify(customNodes));},[customNodes]);
 useEffect(()=>{localStorage.setItem("synaps-experiments",JSON.stringify(experiments));},[experiments]);
 useEffect(()=>{if(inTauri())callNative("list_projects").then(setProjectVersions).catch(e=>note(String(e)))},[]);
 useEffect(()=>{if(!drag)return;const move=e=>setNodes(prev=>prev.map(n=>n.id===drag.id?{...n,x:Math.max(0,drag.x+(e.clientX-drag.startX)/.8),y:Math.max(0,drag.y+(e.clientY-drag.startY)/.8)}:n));const up=()=>setDrag(null);window.addEventListener("pointermove",move);window.addEventListener("pointerup",up);return()=>{window.removeEventListener("pointermove",move);window.removeEventListener("pointerup",up)};},[drag]);
 const note=msg=>{setStatus(msg);setTimeout(()=>setStatus(""),3500)};
 const setSetting=(key,value)=>setSettings(s=>({...s,[key]:value}));
 const updateNode=(id,props)=>setNodes(ns=>ns.map(n=>n.id===id?{...n,...props}:n));
 const discover=async()=>{setLoadingModels(true);try{const list=await callNative("list_models",{provider:{kind:settings.provider,baseUrl:settings.endpoint}});setModels(list);note(`Найдено моделей: ${list.length}`)}catch(e){note(String(e))}finally{setLoadingModels(false)}};
 const refreshLlama=async()=>{try{const s=await callNative("llama_server_status");setLlamaStatus(s);const logs=await callNative("llama_server_logs");setLlamaLogs(logs)}catch(e){note(String(e))}};
 const startLlama=async()=>{try{const s=await callNative("start_llama_server",{executablePath:settings.llamaExecutable,modelPath:settings.llamaModelPath,port:Number(settings.llamaPort),contextSize:Number(settings.llamaContext),gpuLayers:Number(settings.llamaGpuLayers)});setLlamaStatus(s);setSetting("endpoint",`http://127.0.0.1:${settings.llamaPort}`);setSetting("provider","llamacpp");note("llama-server прошёл health-check");await discover();await refreshLlama()}catch(e){note(String(e));await refreshLlama()}};
 const stopLlama=async()=>{try{await callNative("stop_llama_server");await refreshLlama();note("llama-server остановлен")}catch(e){note(String(e))}};
 const addNode=type=>{const ports=PORTS[type]||[["text"],["text"]];const n={id:makeId(),type,cat:type.split(" ")[0].toUpperCase(),x:280+Math.random()*280,y:80+Math.random()*260,inputs:ports[0],outputs:ports[1],text:"",config:{}};setNodes(ns=>[...ns,n]);setSelected(n.id);note(`${type} добавлен`)};
 const loadTemplate=tpl=>{const made=tpl.steps.map((type,i)=>{const ports=PORTS[type]||[["text"],["text"]];return{id:`${tpl.id}-${i}-${makeId()}`,type,cat:type.split(" ")[0].toUpperCase(),x:30+(i%4)*285,y:70+Math.floor(i/4)*210,inputs:ports[0],outputs:ports[1],text:type==="Chat Input"?"Напишите вопрос для шаблона":type==="System Prompt"?"Отвечай точно. Указывай ограничения и неопределённость.":"",config:{}}});const newEdges=[];for(let i=0;i<made.length;i++){for(let j=i+1;j<made.length;j++){const a=made[i],b=made[j];const port=a.outputs.find(x=>b.inputs.includes(x));if(port){newEdges.push({id:makeId(),from:a.id,to:b.id,type:port});break}}}const input=made.find(n=>n.type==="Chat Input"),system=made.find(n=>n.type==="System Prompt"),composer=made.find(n=>n.type==="Prompt Composer");if(composer){for(const source of [input,system])if(source&&!newEdges.some(e=>e.from===source.id&&e.to===composer.id)&&source.outputs.includes("text"))newEdges.push({id:makeId(),from:source.id,to:composer.id,type:"text"})}setNodes(made);setEdges(newEdges);setSelected(made.find(n=>n.type==="LLM Inference")?.id||made[0]?.id);setView("Workspace");setRunState("ready");setTrace([]);note(`Шаблон ${tpl.name} загружен${tpl.ready?"":"; некоторые узлы требуют интеграции"}`)};
 const handlePort=(node,side)=>{if(side==="out"){setConnectFrom(node);note("Выберите вход совместимого типа");return}if(!connectFrom)return;const source=nodes.find(n=>n.id===connectFrom);const target=nodes.find(n=>n.id===node);if(!source||!target||source.id===target.id||!source.outputs.some(t=>target.inputs.includes(t))){note("Типы портов несовместимы");setConnectFrom(null);return}if(edges.some(e=>e.from===source.id&&e.to===node.id)){note("Такое соединение уже есть");setConnectFrom(null);return}setEdges(es=>[...es,{id:makeId(),from:source.id,to:node.id,type:source.outputs.find(t=>target.inputs.includes(t))}]);setConnectFrom(null);note("Порт соединён")};
 const saveProject=async()=>{const project={version:1,name:settings.project,nodes,edges,settings:{...settings,apiKey:undefined}};const json=JSON.stringify(project);localStorage.setItem("synaps-project",json);if(inTauri()){try{const version=await callNative("save_project",{name:settings.project,projectJson:json});setProjectVersions(v=>[version,...v]);note(`SQLite: сохранена версия ${version.version}`)}catch(e){note(`Локально сохранено; SQLite: ${String(e)}`)}}else note("Сохранено в браузере; SQLite доступна в desktop-сборке")};
 const exportProject=()=>{const file=new Blob([JSON.stringify({version:1,name:settings.project,nodes,edges,settings:{...settings,apiKey:undefined}},null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(file);a.download="synaps-project.json";a.click();URL.revokeObjectURL(a.href)};
 const importProject=e=>{const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const p=JSON.parse(r.result);if(!Array.isArray(p.nodes)||!Array.isArray(p.edges)||p.nodes.length>500||p.edges.length>2000)throw Error();const ids=new Set();const validNodes=p.nodes.filter(n=>n&&typeof n.id==="string"&&TYPES.includes(n.type)&&Number.isFinite(n.x)&&Number.isFinite(n.y)&&Array.isArray(n.inputs)&&Array.isArray(n.outputs)&&!ids.has(n.id)&&ids.add(n.id)).map(n=>({...n,text:typeof n.text==="string"?n.text:""}));if(validNodes.length!==p.nodes.length)throw Error();const validEdges=p.edges.filter(edge=>edge&&typeof edge.id==="string"&&ids.has(edge.from)&&ids.has(edge.to)&&validNodes.some(n=>n.id===edge.from&&n.outputs.some(t=>validNodes.find(m=>m.id===edge.to)?.inputs.includes(t))));if(validEdges.length!==p.edges.length)throw Error();setNodes(validNodes);setEdges(validEdges);if(p.settings)setSettings(s=>({...s,...p.settings}));note("Проект импортирован")}catch{note("Некорректный файл проекта")}};r.readAsText(f);e.target.value=""};
 const promptPreview=useMemo(()=>{const user=nodes.find(n=>n.type==="Chat Input")?.text||"";const sys=nodes.find(n=>n.type==="System Prompt")?.text||"";const ctx=nodes.find(n=>n.type==="Context")?.text||"";return {sys,user,ctx}},[nodes]);
 const run=async()=>{if(runState==="running")return;setRunState("running");setResult("");setMetrics(null);cancelRef.current=false;requestRef.current=makeId();const started=performance.now();const logs=[];const log=(node,detail,state="done",data=null)=>{logs.push({node,detail,state,time:new Date().toLocaleTimeString(),elapsedMs:Math.round(performance.now()-started),data});setTrace([...logs])};
  const byId=new Map(nodes.map(n=>[n.id,n]));const incoming=new Map(nodes.map(n=>[n.id,edges.filter(e=>e.to===n.id)]));const indegree=new Map(nodes.map(n=>[n.id,incoming.get(n.id).length]));const queue=nodes.filter(n=>indegree.get(n.id)===0).map(n=>n.id);const order=[];while(queue.length){const id=queue.shift();order.push(id);for(const e of edges.filter(x=>x.from===id)){indegree.set(e.to,indegree.get(e.to)-1);if(indegree.get(e.to)===0)queue.push(e.to)}}
  if(order.length!==nodes.length){log("Graph Validator","Граф содержит цикл или недостижимую структуру; исправьте соединения.","blocked");setRunState("blocked");return}
  const values=new Map();let lastAnswer="";
  try{for(const id of order){if(cancelRef.current)throw new Error("Запуск отменён");const node=byId.get(id);const links=incoming.get(id)||[];const inputs=links.map(e=>({edge:e,node:byId.get(e.from),value:values.get(e.from)}));const ts=performance.now();setActiveNode(id);log(node.type,`Исполняется ${links.length} входов`,"running");let value;
    if(node.type==="Chat Input"||node.type==="User Prompt Input"||node.type==="System Prompt"||node.type==="System Prompt Input"||node.type==="Context"||node.type==="Variable Input"||node.type==="Manual Trigger"){value=node.text||""}
    else if(node.type==="Image Input"){value=node.config?.imageData?{dataUrl:node.config.imageData,name:node.config.fileName,mime:node.config.mime,width:node.config.width,height:node.config.height,size:node.config.size}:null;if(!value)throw new Error("Добавьте изображение в узел Image Input")}
    else if(node.type==="Prompt Composer"||node.type==="Prompt Template"||node.type==="Instruction Composer"||node.type==="Prompt Builder"){const sys=inputs.find(x=>/System Prompt/.test(x.node?.type))?.value??promptPreview.sys;const safetyInput=inputs.find(x=>/Safety Review|Safety Classifier|Prompt Injection Detector/.test(x.node?.type))?.value;const user=safetyInput?.text??inputs.find(x=>/Chat Input|User Prompt/.test(x.node?.type))?.value??inputs.find(x=>typeof x.value==="string"&&x.value.length)?.value??promptPreview.user;const ctx=inputs.filter(x=>/Context|Memory|Document/.test(x.node?.type)).map(x=>typeof x.value==="string"?x.value:JSON.stringify(x.value??""));value=[{role:"system",content:[sys,ctx.length?`Контекст:
${ctx.join("\n")}`:""].filter(Boolean).join("\n\n")},{role:"user",content:String(user??"")}];}
    else if(node.type==="Context Merger"||node.type==="Context Injector"||node.type==="Text Merger"||node.type==="Text Formatter"){value=inputs.map(x=>typeof x.value==="string"?x.value:JSON.stringify(x.value??"")).filter(Boolean).join(node.type==="Text Merger"?(node.config?.separator||"\n") : "\n\n");if(node.type==="Text Formatter")value=value.replace(/[ \t]+/g," ").trim()}
    else if(node.type==="Output Length Limiter"){const text=String(inputs[0]?.value??"");const cap=Math.max(1,Number(node.config?.maxChars)||2000);value=text.slice(0,cap)}
    else if(node.type==="JSON Parser"||node.type==="JSON Validator"){const raw=inputs[0]?.value??node.text??"";if(node.type==="JSON Validator"&&raw&&typeof raw==="object")value=raw;else{const text=String(raw);try{value=JSON.parse(text)}catch{throw new Error(`Некорректный JSON в узле ${node.type}`)}}}
    else if(node.type==="JSON Builder"){value=Object.fromEntries(inputs.map((x,i)=>[`field_${i+1}`,x.value??null]))}
    else if(node.type==="Fact Extraction"||node.type==="Code Preview"||node.type==="Prompt Inspector"||node.type==="Model Information"||node.type==="Inference Configuration"||node.type==="Instruction Priority"||node.type==="Few-Shot Examples"||node.type==="Prompt Variables"||node.type==="Output Validator"||node.type==="Classifier"){value=inputs.at(-1)?.value??node.text??""}
    else if(node.type==="Model Comparison"){value=inputs.map((x,i)=>`Model ${i+1}: ${typeof x.value==="string"?x.value:JSON.stringify(x.value)}`).join("\n\n") }
    else if(node.type==="Image Preview"){value=inputs[0]?.value??"Изображение не выбрано"}
    else if(node.type==="Document Search"||node.type==="RAG Retriever"||node.type==="Document Chunker"||node.type==="File Reader"){throw new Error(`Для узла «${node.type}» нужен источник документов, который не настроен`)}
    else if(node.type==="Text Splitter"){value=String(inputs[0]?.value??"").split(node.config?.separator||"\n")}
    else if(node.type==="Safety Review"||node.type==="Input Safety Classifier"||node.type==="Output Safety Classifier"||node.type==="Prompt Injection Detector"){const text=String(inputs[0]?.value??"");const flags=[/ignore (all )?(previous|prior) instructions/i,/reveal (the )?(system|hidden) prompt/i,/password\s*[:=]/i].filter(r=>r.test(text)).map(r=>r.source);value={text,review:{flagged:flags.length>0,heuristicFlags:flags,warning:"Эвристическая проверка; не гарантирует безопасность."}}}
    else if(node.type==="Cache"||node.type==="Retry"||node.type==="Router"||node.type==="Model Router"||node.type==="Execution Result"||node.type==="Debug Output"||node.type==="Chat Output"||node.type==="Structured Output"||node.type==="JSON Output"||node.type==="Output Validator"){value=inputs.at(-1)?.value??node.text??""}
    else if(node.type==="Delay"){await new Promise(r=>setTimeout(r,Math.min(5000,Math.max(0,Number(node.config?.milliseconds)||0))));value=inputs[0]?.value??""}
    else if(node.type==="LLM Inference"||node.type==="Vision Model"||node.type==="Model A"||node.type==="Model B"||node.type==="Model C"){if(!settings.model)throw new Error("Выберите модель в настройках перед запуском");let messages=Array.isArray(inputs.find(x=>Array.isArray(x.value))?.value)?inputs.find(x=>Array.isArray(x.value)).value:[{role:"system",content:promptPreview.sys},{role:"user",content:promptPreview.user}];const imagePayload=inputs.find(x=>x.value&&typeof x.value==="object"&&x.value.dataUrl)?.value;if(node.type==="Vision Model"&&imagePayload?.dataUrl){messages=messages.map(m=>m.role==="user"?{...m,content:[{type:"text",text:typeof m.content==="string"?m.content:JSON.stringify(m.content)},{type:"image_url",image_url:{url:imagePayload.dataUrl}}]}:m)}let responseText="";let streamError=null;const requestId=`${requestRef.current}-${id}`;requestRef.current=requestId;const stats={firstChunkMs:null,promptTokens:null,completionTokens:null,elapsedMs:null};await streamNative({requestId,provider:{kind:settings.provider,baseUrl:settings.endpoint},model:node.config?.model||settings[node.type+"Model"]||settings.model,messages,options:{temperature:Number(settings.temperature),top_p:Number(settings.topP),...(settings.provider==="ollama"?{num_predict:Number(settings.maxTokens),num_ctx:Number(settings.contextTokens)}:{max_tokens:Number(settings.maxTokens)})}},ev=>{if(ev.kind==="delta"){responseText+=ev.delta||"";setResult(responseText);if(ev.firstChunkMs!=null)stats.firstChunkMs=ev.firstChunkMs;if(ev.promptTokens!=null)stats.promptTokens=ev.promptTokens;if(ev.completionTokens!=null)stats.completionTokens=ev.completionTokens;if(ev.providerTokensPerSecond!=null)stats.providerTokensPerSecond=ev.providerTokensPerSecond;if(ev.backendTtftMs!=null)stats.backendTtftMs=ev.backendTtftMs;}else if(ev.kind==="done"||ev.kind==="cancelled"){stats.elapsedMs=ev.elapsedMs;if(ev.promptTokens!=null)stats.promptTokens=ev.promptTokens;if(ev.completionTokens!=null)stats.completionTokens=ev.completionTokens;if(ev.providerTokensPerSecond!=null)stats.providerTokensPerSecond=ev.providerTokensPerSecond;if(ev.backendTtftMs!=null)stats.backendTtftMs=ev.backendTtftMs;setMetrics({...stats});}else if(ev.kind==="error"){streamError=ev.error||"Ошибка потока"}});if(streamError)throw new Error(streamError);if(cancelRef.current)throw new Error("Запуск отменён");value=responseText;lastAnswer=responseText;}
    else if(node.type==="Memory Writer"){const text=String(inputs[0]?.value??"");const key=`synaps-memory-${settings.project}`;const prior=readJson(key,[]);const entries=[...prior,{text,at:new Date().toISOString()}].slice(-50);localStorage.setItem(key,JSON.stringify(entries));value=text}
    else if(node.type==="Conversation Memory"||node.type==="Short-Term Memory"){value=readJson(`synaps-memory-${settings.project}`,[]).map(x=>x.text).join("\n")}
    else {throw new Error(`Узел «${node.type}» пока не имеет безопасного исполнителя`) }
    values.set(id,value);const out=typeof value==="string"?value:JSON.stringify(value);log(node.type,`Завершено за ${Math.round(performance.now()-ts)} ms`,"done",{input:inputs.map(x=>x.value),output:value});if(node.type==="Chat Output")lastAnswer=String(value??"");}
    setActiveNode(null);setResult(lastAnswer||String(values.get(order.at(-1))??""));updateNode(nodes.find(n=>n.type==="Chat Output")?.id||"output",{text:lastAnswer});setMetrics(m=>({...m,totalMs:Math.round(performance.now()-started),responseChars:lastAnswer.length,tokensPerSecond:m?.completionTokens&&m?.elapsedMs?Math.round(m.completionTokens/(m.elapsedMs/1000)*10)/10:null}));setRunState("done")}
  catch(e){setActiveNode(null);const message=String(e);log(message.includes("отменён")?"Cancellation":"Execution Error",message,"blocked");setRunState(message.includes("отменён")?"cancelled":"blocked")}
 };
 const cancelRun=async()=>{cancelRef.current=true;if(requestRef.current&&inTauri()){try{await callNative("cancel_inference",{requestId:`${requestRef.current}-${nodes.find(n=>n.type==="LLM Inference")?.id||"model"}`})}catch(e){note(String(e))}}note("Отмена запрошена")};
 const addSkill=()=>{if(!newSkill.name.trim()||!newSkill.instructions.trim()){note("Нужны название и инструкции навыка");return}setSkills(s=>[...s,{...newSkill,id:makeId(),createdAt:new Date().toISOString()}]);setNewSkill({name:"",description:"",instructions:"",version:"1.0.0"});setSkillModal(false);note("Навык сохранён локально")};
 const exportSkill=skill=>{const blob=new Blob([JSON.stringify({manifestVersion:1,name:skill.name,version:skill.version,description:skill.description,instructions:skill.instructions},null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`${skill.name.toLowerCase().replace(/[^a-z0-9-]+/g,"-")||"synaps-skill"}.json`;a.click();URL.revokeObjectURL(a.href)};
 const createCustomNode=()=>{if(!nodeDraft.name.trim()){note("Укажите имя узла");return}const item={...nodeDraft,id:makeId(),inputs:[nodeDraft.inputType],outputs:[nodeDraft.outputType],handlerStatus:"manifest-only",createdAt:new Date().toISOString()};setCustomNodes(xs=>[item,...xs]);setNodeDraft({name:"",description:"",category:"PROCESSING",version:"1.0.0",inputType:"text",outputType:"text",documentation:""});setCustomModal(false);note("Manifest сохранён; исполнителя нет")};
 const exportCustomNode=item=>{const manifest={manifestVersion:1,name:item.name,version:item.version,description:item.description,category:item.category,inputs:item.inputs.map(type=>({name:"input",type})),outputs:item.outputs.map(type=>({name:"output",type})),documentation:item.documentation,execution:{status:"not-implemented",script:null},dependencies:[]};const blob=new Blob([JSON.stringify(manifest,null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`${item.name.toLowerCase().replace(/[^a-z0-9-]+/g,"-")||"custom-node"}.json`;a.click();URL.revokeObjectURL(a.href)};
 const saveExperiment=()=>{if(!result){note("Сначала выполни граф");return}const entry={id:makeId(),name:`${settings.model||"model"} · ${new Date().toLocaleString()}`,model:settings.model,provider:settings.provider,prompt:promptPreview.user,response:result,metrics,trace,createdAt:new Date().toISOString(),rating:0,notes:""};setExperiments(xs=>[entry,...xs]);note("Результат эксперимента сохранён локально")};
 const exportExperiments=()=>{const blob=new Blob([JSON.stringify(experiments,null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="synaps-experiments.json";a.click();URL.revokeObjectURL(a.href)};
 const restoreVersion=async version=>{try{const v=await callNative("restore_project_version",{versionId:version.id});const p=JSON.parse(v.json);setNodes(p.nodes);setEdges(p.edges);if(p.settings)setSettings(s=>({...s,...p.settings}));note(`Восстановлена версия ${v.version}`);setView("Workspace")}catch(e){note(String(e))}};
 const nodeIcon=type=>ICONS[type]||Sparkles;
 const switchView=v=>{setView(v);if(v==="Project versions"&&inTauri())callNative("list_projects").then(setProjectVersions).catch(e=>note(String(e)))};
 const labels=[{name:"Workspace",icon:Network},{name:"Templates",icon:List},{name:"Brain Inspector",icon:Activity},{name:"Model POV",icon:FileText},{name:"Experiments",icon:Layers},{name:"Project versions",icon:RefreshCw},{name:"Context & prompts",icon:Layers},{name:"LLM settings",icon:SlidersHorizontal},{name:"Skills",icon:Sparkles},{name:"Custom Nodes",icon:Code2},{name:"Theme",icon:Settings2}];
 return <div className="app-shell"><aside className="rail"><div className="brand-mark">S</div><nav>{labels.map(({name,icon:Icon})=><button key={name} className={`rail-button ${view===name?"active":""}`} title={name} onClick={()=>switchView(name)}><Icon size={18}/></button>)}</nav><div className="rail-bottom"><button className="rail-button" title="Экспорт проекта" onClick={exportProject}><Download size={17}/></button><label className="rail-button file-button" title="Импорт проекта"><Upload size={17}/><input type="file" accept=".json,application/json" onChange={importProject}/></label></div></aside>
 <main className="main"><header className="topbar"><div className="crumb"><span className="eyebrow">SYNAPS / LOCAL STUDIO</span><span className="crumb-sep">/</span><b>{view}</b></div><div className="top-actions"><span className={`runtime ${inTauri()?"connected":""}`}><i/>{inTauri()?"Desktop runtime":"Browser preview"}</span><button className="btn secondary" onClick={exportProject}><Download size={15}/> Экспорт</button><button className="btn primary" onClick={saveProject}><Save size={15}/> Сохранить</button></div></header>
 {view==="Workspace"?<><div className="project-head"><div><span className="eyebrow">PROJECT</span><input className="project-name" value={settings.project} onChange={e=>setSetting("project",e.target.value)}/><span className="local-tag"><LockKeyhole size={12}/> local-only</span></div><div className="provider-summary"><span className={`dot ${inTauri()?"green":"gray"}`}/>{settings.provider} · {settings.model||"модель не выбрана"}</div></div><div className="workarea"><aside className="side-panel library"><div className="panel-heading"><div><span className="eyebrow">CONSTRUCT</span><h2>Узлы графа</h2></div><button className="icon-btn" title="Добавить узел" onClick={()=>addNode("Text Formatter")}><Plus size={17}/></button></div><div className="search"><Search size={14}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Найти узел"/></div><div className="library-list">{TYPES.filter(t=>t.toLowerCase().includes(query.toLowerCase())).map(type=>{const Icon=nodeIcon(type);return <button className="lib-item" key={type} onClick={()=>addNode(type)}><span className="node-mini"><Icon size={15}/></span><span><b>{type}</b><small>{type==="LLM Inference"?"Запрос к локальной модели":type==="Context"?"Вспомогательный контекст":(["Prompt Composer","Text Formatter","JSON Parser","JSON Validator","Output Length Limiter","Safety Review","Chat Input","System Prompt","Chat Output","Context","Conversation Memory","Short-Term Memory","Delay","JSON Builder","Text Splitter","Text Merger","Context Merger","Model Comparison","Prompt Template"].includes(type)?"Исполнитель реализован":"Расширение: обработчик не подключён")}</small></span><Plus size={14}/></button>})}</div><div className="provider-box"><span className="eyebrow">LOCAL PROVIDER</span><b>{settings.provider}</b><small>{settings.endpoint}</small><button className="btn secondary full" disabled={loadingModels} onClick={discover}>{loadingModels?<LoaderCircle className="spin" size={15}/>:<RefreshCw size={14}/>}Найти модели</button>{models.length>0&&<select value={settings.model} onChange={e=>setSetting("model",e.target.value)}><option value="">Выбрать модель</option>{models.map((m,i)=><option key={i} value={typeof m==="string"?m:(m.key||m.id||m.name)}>{typeof m==="string"?m:(m.key||m.id||m.name)}</option>)}</select>}</div></aside>
 <section className="canvas"><div className="canvas-head"><div className="tabs"><button className="tab active">Graph <span>{nodes.length}</span></button><button className="tab" onClick={()=>switchView("Context & prompts")}>Effective prompt</button></div><div className="canvas-toolbar"><button className="icon-btn" title="Zoom out" onClick={()=>document.querySelector(".graph")?.style.setProperty("--scale",".72")}><span>−</span></button><span>80%</span><button className="icon-btn" title="Zoom in" onClick={()=>document.querySelector(".graph")?.style.setProperty("--scale",".9")}><span>+</span></button></div></div><div className="canvas-view"><div className="canvas-label">● GRAPH CANVAS <span>{connectFrom?"Выберите совместимый вход":"Тяни узлы · соединяй типизированные порты"}</span></div><div className="graph" style={{transform:"scale(var(--scale, .8))"}}><svg className="edges" width="1280" height="640">{edges.map(e=>{const a=nodes.find(n=>n.id===e.from),b=nodes.find(n=>n.id===e.to);if(!a||!b)return null;const x=a.x+224,y=a.y+81,x2=b.x,y2=b.y+81,k=Math.max(40,(x2-x)*.45);return <g key={e.id}><path d={`M${x} ${y} C${x+k} ${y},${x2-k} ${y2},${x2} ${y2}`} className="edge"/><path d={`M${x} ${y} C${x+k} ${y},${x2-k} ${y2},${x2} ${y2}`} className="edge-hit" onClick={()=>setEdges(es=>es.filter(z=>z.id!==e.id))}/></g>})}</svg>{nodes.map(n=>{const Icon=nodeIcon(n.type);const state=trace.findLast?.(t=>t.node===n.type)?.state||"idle";return <article key={n.id} className={`graph-node ${selected===n.id?"selected":""} ${state}`} style={{left:n.x,top:n.y}} onPointerDown={e=>{if(e.target.closest("button,textarea,input"))return;setSelected(n.id);setDrag({id:n.id,startX:e.clientX,startY:e.clientY,x:n.x,y:n.y})}}><div className="node-head"><span className="node-icon"><Icon size={15}/></span><small>{n.cat}</small><span className="node-state">{state.toUpperCase()}</span></div><b>{n.type}</b><p>{n.type==="Chat Input"?n.text||"Введите вопрос":n.type==="System Prompt"?n.text||"Укажите системные инструкции":n.type==="Context"?n.text||"Контекст не заполнен":n.type==="LLM Inference"?settings.model||"Выберите модель":n.type==="Chat Output"?n.text||"Ожидает ответа":n.type==="Prompt Composer"?"Система + контекст + пользователь":"Обработка текста"}</p><div className="node-foot"><span>{n.inputs.length?`${n.inputs.join(" · ")} →`:"SOURCE"}</span><span>{n.outputs.join(" · ")}</span></div>{n.inputs.map((p,i)=><button className={`port in ${connectFrom?"available":""}`} style={{top:59+i*19}} key={i} aria-label={`Input ${p} on ${n.type}`} title={`Вход ${p}`} onClick={()=>handlePort(n.id,"in")}/>)}{n.outputs.map((p,i)=><button className="port out" style={{top:59+i*19}} key={i} aria-label={`Output ${p} from ${n.type}`} title={`Выход ${p}`} onClick={()=>handlePort(n.id,"out")}/>)}</article>})}</div><div className="canvas-hint">Перетаскивай узлы · кликни выход, затем вход для соединения</div><div className="minimap">OVERVIEW<div className="mini-dots">{nodes.map(n=><i key={n.id} style={{left:`${n.x/13}%`,top:`${n.y/6}%`}}/>)}</div></div></div><footer className="runbar"><div className="run-status"><i className={runState}/><b>{runState==="ready"?"Готов":runState==="running"?"Выполняется":runState==="done"?"Завершено":runState==="cancelled"?"Отменено":"Остановлено"}</b><span>{runState==="blocked"?"Проверь runtime и модель":"Пайплайн · локальный запуск"}</span></div><button className={`btn ${runState==="running"?"secondary":"primary"}`} onClick={runState==="running"?cancelRun:run}>{runState==="running"?<><X size={15}/> Отменить</>:<><Zap size={16}/> Запустить граф</>}</button></footer></section>
 <aside className="side-panel inspect"><div className="panel-heading"><div><span className="eyebrow">OBSERVABILITY</span><h2>Инспектор</h2></div><Activity size={17}/></div><div className="inspector-tabs"><button className="active">Trace</button><button onClick={()=>switchView("Context & prompts")}>Prompt</button><button onClick={()=>setShowContext(s=>!s)}>Context</button></div><div className="trace-list">{trace.length?trace.map((t,i)=><div className={`trace-item ${t.state}`} key={i}><span className="trace-symbol">{t.state==="blocked"?"!":"✓"}</span><div><b>{t.node}</b><small>{t.detail}</small></div><time>{t.time}</time></div>):<p className="muted">Запусти граф, чтобы посмотреть порядок исполнения и фактические данные.</p>}</div>{result&&<div className="result-box"><span className="eyebrow">MODEL OUTPUT</span><p>{result}</p></div>}<div className="metrics"><span className="eyebrow">RUNTIME METRICS</span><strong>{metrics?.totalMs!=null?`Общее время: ${metrics.totalMs} ms`:"Нет измерений"}</strong><small>{metrics?.firstChunkMs!=null?`Первый chunk: ${metrics.firstChunkMs} ms · Ответ: ${metrics.responseChars||0} знаков`:"Токены и latency отображаются только если их сообщает backend."}</small><button className="plain-action" onClick={()=>switchView("Brain Inspector")}>Подробный trace →</button></div><div className="selection"><span className="eyebrow">SELECTED NODE</span>{chosen?<><b>{chosen.type}</b>{["Chat Input","System Prompt","Context"].includes(chosen.type)&&<textarea aria-label={`${chosen.type} text`} value={chosen.text} onChange={e=>updateNode(chosen.id,{text:e.target.value})} placeholder={chosen.type==="Context"?"Добавьте фоновые сведения для модели...":"Введите текст..."}/>}{chosen.type==="Image Input"&&<><label className="image-upload">Выбрать изображение<input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>2*1024*1024){note("Для локального хранения лимит изображения 2 МБ");return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>updateNode(chosen.id,{config:{...chosen.config,imageData:String(reader.result),fileName:file.name,mime:file.type,width:img.naturalWidth,height:img.naturalHeight,size:file.size}});img.src=String(reader.result)};reader.readAsDataURL(file)}}/></label>{chosen.config?.imageData&&<div className="image-detail"><img src={chosen.config.imageData} alt="Original selected input"/><small>{chosen.config.fileName} · {chosen.config.width}×{chosen.config.height} · {chosen.config.mime} · {(chosen.config.size/1024).toFixed(0)} KB</small><button className="plain-action" onClick={()=>updateNode(chosen.id,{config:{}})}>Удалить изображение из проекта</button></div>}</>}<button className="delete" onClick={()=>{setNodes(ns=>ns.filter(n=>n.id!==chosen.id));setEdges(es=>es.filter(e=>e.from!==chosen.id&&e.to!==chosen.id));setSelected(null)}}><Trash2 size={13}/> Удалить узел</button></>:<small>Выбери узел на графе</small>}</div></aside></div></>:null}
 {view==="Templates"&&<SettingsPage title="Библиотека архитектур" eyebrow="READY-MADE GRAPHS" icon={List}><div className="template-grid">{TEMPLATES.map(t=><article className="template-card" key={t.id}><div className="template-top"><span className="template-icon"><Network size={17}/></span><span className={`status-pill ${t.ready?"implemented":"partial"}`}>{t.ready?"Базовый путь":"Частично"}</span></div><h3>{t.name}</h3><p>{t.desc}</p><div className="template-steps">{t.steps.map((step,i)=><span key={`${step}-${i}`}>{step}{i<t.steps.length-1?<ArrowRight size={11}/>:null}</span>)}</div><button className="btn secondary" onClick={()=>loadTemplate(t)}>Открыть граф</button></article>)}</div><div className="callout">Шаблоны vision, research и multi-model включены как стартовые схемы; их мультимодальные/retrieval/сравнительные узлы не считаются полностью реализованными в этом выпуске.</div></SettingsPage>}
 {view==="Brain Inspector"&&<SettingsPage title="Brain Inspector" eyebrow="MEASURED EXECUTION TRACE" icon={Activity}><div className="inspector-dashboard"><div className="form-card"><span className="eyebrow">RUN SUMMARY</span><div className="metric-cards"><div><small>Wall time</small><b>{metrics?.totalMs!=null?`${metrics.totalMs} ms`:"—"}</b></div><div><small>First client chunk</small><b>{metrics?.firstChunkMs!=null?`${metrics.firstChunkMs} ms`:"—"}</b></div><div><small>Backend TTFT</small><b>{metrics?.backendTtftMs!=null?`${metrics.backendTtftMs} ms`:"Unavailable"}</b></div><div><small>Provider completion tokens</small><b>{metrics?.completionTokens??"Unavailable"}</b></div><div><small>Provider prompt tokens</small><b>{metrics?.promptTokens??"Unavailable"}</b></div><div><small>Provider tokens/sec</small><b>{metrics?.providerTokensPerSecond??metrics?.tokensPerSecond??"Unavailable"}</b></div></div><p>Токены показываются только если их сообщил endpoint. Клиентские chunk-записи не называются токенами.</p></div><div className="form-card"><span className="eyebrow">EXECUTION ORDER</span>{trace.length?trace.map((t,i)=><details className="brain-row" key={`${t.node}-${i}`} open={i===trace.length-1}><summary><b>{String(i+1).padStart(2,"0")} · {t.node}</b><span>{t.elapsedMs} ms</span><small>{t.detail}</small></summary>{t.data&&<pre>{JSON.stringify(t.data,null,2)}</pre>}</details>):<p className="muted">Запустите граф, чтобы записать наблюдаемые значения и время узлов.</p>}</div><div className="callout">Это trace реально наблюдаемых клиентом операций, а не скрытая цепочка мыслей модели. Нет данных от backend: значение оставлено пустым.</div></div></SettingsPage>}
 {view==="Experiments"&&<SettingsPage title="Experiment Lab" eyebrow="COMPARE OBSERVED RUNS" icon={Layers} action={<div className="button-row"><button className="btn secondary" onClick={exportExperiments} disabled={!experiments.length}><Download size={14}/> Экспорт</button><button className="btn primary" onClick={saveExperiment} disabled={!result}><Plus size={14}/> Сохранить текущий запуск</button></div>}><p className="muted">Сравнения и субъективные пользовательские оценки, не объективный бенчмарк.</p>{experiments.length?<div className="skills-grid">{experiments.map(exp=><article className="skill-card" key={exp.id}><span className="eyebrow">{exp.provider} · {exp.model||"model"}</span><h3>{exp.name}</h3><p>{exp.prompt}</p><details><summary>Результат</summary><pre>{exp.response}</pre></details><div className="field-label">Оценка пользователя: <select value={exp.rating} onChange={e=>setExperiments(xs=>xs.map(x=>x.id===exp.id?{...x,rating:Number(e.target.value)}:x))}><option value="0">Не оценено</option><option value="1">1 · слабо</option><option value="2">2 · приемлемо</option><option value="3">3 · хорошо</option><option value="4">4 · очень хорошо</option><option value="5">5 · отлично</option></select></div><textarea className="experiment-note" placeholder="Заметка о запуске..." value={exp.notes} onChange={e=>setExperiments(xs=>xs.map(x=>x.id===exp.id?{...x,notes:e.target.value}:x))}/></article>)}</div>:<div className="empty-skills"><Layers size={24}/><b>Запусков пока нет</b><span>Выполните граф, затем сохраните результат для журнала сравнения.</span></div>}</SettingsPage>}
 {view==="Project versions"&&<SettingsPage title="Версии проектов" eyebrow="SQLITE PROJECT HISTORY" icon={RefreshCw} action={<button className="btn primary" onClick={saveProject}><Save size={14}/> Сохранить новую версию</button>}><div className="callout">В Tauri-сборке версии сохраняются в SQLite. В browser preview используется только localStorage.</div>{projectVersions.length?<div className="version-list">{projectVersions.map(v=><article className="version-row" key={v.id}><div><b>{v.name} · v{v.version}</b><small>{new Date(v.savedAt*1000).toLocaleString()} · {v.json.length} символов</small></div><button className="btn secondary" onClick={()=>restoreVersion(v)}><RefreshCw size={14}/> Восстановить</button></article>)}</div>:<div className="empty-skills"><RefreshCw size={24}/><b>История версий пока пуста</b><span>Сохраните проект в desktop-приложении, чтобы создать первую версию SQLite.</span></div>}</SettingsPage>}
 {view==="Model POV"&&<SettingsPage title="Model POV · изображение" eyebrow="CLIENT-VISIBLE MULTIMODAL INPUT" icon={FileText}><div className="callout">Показываем оригинальный файл и payload, который собирает клиент. Скрытые server-side crops/patches недоступны и здесь не моделируются.</div><div className="pov-grid">{nodes.filter(n=>n.type==="Image Input").map(n=><article className="form-card" key={n.id}><span className="eyebrow">ORIGINAL IMAGE</span><h3>{n.config?.fileName||"Изображение не выбрано"}</h3>{n.config?.imageData?<><img className="pov-image" src={n.config.imageData} alt="Original input image"/><p>{n.config.width}×{n.config.height} · {n.config.mime} · {((n.config.size||0)/1024).toFixed(1)} KB</p><span className="eyebrow">CLIENT REQUEST PAYLOAD</span><pre>{`image_url: data URL (${n.config.mime}), ${n.config.size} bytes before base64 encoding
Provider receives the uploaded original; internal preprocessing is unknown.`}</pre></>:<p>Выберите узел Image Input и загрузите изображение до 2 МБ.</p>}<button className="btn secondary" onClick={()=>{setSelected(n.id);setView("Workspace")}}>Открыть узел</button></article>)}</div><div className="form-card wide"><span className="eyebrow">LIMITATIONS</span><p>Поддерживается передача изображения через Ollama chat image array и OpenAI-compatible `image_url`. LM Studio Native endpoint в этой сборке отклонит image payload. Документы, аудио и фактическое преобразование backend пока не реализованы.</p></div></SettingsPage>}
 {view==="Context & prompts"&&<SettingsPage title="Контекст и системный промпт" eyebrow="PROMPT ENGINEERING" icon={Layers}><div className="form-grid"><div className="form-card"><span className="eyebrow">SYSTEM INSTRUCTIONS</span><p>Явные инструкции, добавляемые этим проектом. Скрытые инструкции провайдера клиент не видит.</p><textarea value={promptPreview.sys} onChange={e=>updateNode("system",{text:e.target.value})} rows="9" placeholder="Роль, стиль, ограничения ответа..."/></div><div className="form-card"><span className="eyebrow">CONTEXT WINDOW</span><p>Прозрачный контекст пользователя. В этой версии ручной ввод; поиск и автоматическая обрезка ещё не подключены.</p><textarea value={promptPreview.ctx} onChange={e=>updateNode("context",{text:e.target.value})} rows="9" placeholder="Добавьте документы, заметки или факты для модели..."/><div className="field-row"><label>Символов в контексте <b>{promptPreview.ctx.length}</b></label><label>Токены <b>оценка недоступна</b></label></div></div><div className="form-card wide"><span className="eyebrow">EFFECTIVE REQUEST PREVIEW</span><pre>{`SYSTEM\n${promptPreview.sys||"(нет системного промпта)"}\n\nCONTEXT\n${promptPreview.ctx||"(контекст не добавлен)"}\n\nUSER\n${promptPreview.user||"(нет сообщения)"}`}</pre></div></div></SettingsPage>}
 {view==="LLM settings"&&<SettingsPage title="Настройки модели" eyebrow="INFERENCE CONTROL" icon={Radio}><div className="form-grid"><div className="form-card"><span className="eyebrow">PROVIDER</span><label className="field-label">Движок<select value={settings.provider} onChange={e=>{const next=e.target.value;setSetting("provider",next);if(settings.endpoint==="http://127.0.0.1:11434"||settings.endpoint==="http://127.0.0.1:1234"||settings.endpoint==="http://127.0.0.1:8080")setSetting("endpoint",next==="ollama"?"http://127.0.0.1:11434":next==="llamacpp"?"http://127.0.0.1:8080":"http://127.0.0.1:1234")}}><option value="ollama">Ollama</option><option value="lmstudio-native">LM Studio Native API</option><option value="openai-compatible">OpenAI-compatible / LM Studio</option><option value="llamacpp">llama.cpp server</option></select></label><label className="field-label">Локальный API URL<input value={settings.endpoint} onChange={e=>setSetting("endpoint",e.target.value)} placeholder="http://127.0.0.1:11434"/></label><div className="button-row"><button className="btn secondary" onClick={discover} disabled={loadingModels}>{loadingModels?<LoaderCircle className="spin" size={15}/>:<RefreshCw size={15}/>}Обнаружить модели</button><small>{inTauri()?"Запрос отправляется только из desktop runtime":"Для провайдера нужна desktop-сборка"}</small></div><label className="field-label">Модель<select value={settings.model} onChange={e=>setSetting("model",e.target.value)}><option value="">{models.length?"Выберите модель":"Сначала обнаружьте модели"}</option>{models.map((m,i)=><option key={i} value={typeof m==="string"?m:(m.key||m.id||m.name)}>{typeof m==="string"?m:(m.key||m.id||m.name)}</option>)}</select><input value={settings.model} onChange={e=>setSetting("model",e.target.value)} placeholder="Или укажите ID модели вручную"/></label></div>{settings.provider==="llamacpp"&&<div className="form-card"><span className="eyebrow">MANAGED LLAMA-SERVER</span><p>Запускается только явно выбранный llama-server.exe. Хост всегда привязан к 127.0.0.1; бинарник не загружается приложением.</p><label className="field-label">Путь к llama-server.exe<input value={settings.llamaExecutable} onChange={e=>setSetting("llamaExecutable",e.target.value)} placeholder="C:\tools\llama-server.exe"/></label><label className="field-label">Путь к GGUF<input value={settings.llamaModelPath} onChange={e=>setSetting("llamaModelPath",e.target.value)} placeholder="D:\models\model.gguf"/></label><div className="form-grid"><label className="field-label">Порт<input type="number" min="1024" max="65535" value={settings.llamaPort} onChange={e=>setSetting("llamaPort",e.target.value)}/></label><label className="field-label">Контекст<input type="number" min="256" max="131072" value={settings.llamaContext} onChange={e=>setSetting("llamaContext",e.target.value)}/></label><label className="field-label">GPU layers<input type="number" min="-1" max="999" value={settings.llamaGpuLayers} onChange={e=>setSetting("llamaGpuLayers",e.target.value)}/></label></div><div className="button-row"><button className="btn primary" onClick={startLlama} disabled={llamaStatus.running}>Запустить и проверить</button><button className="btn secondary" onClick={stopLlama} disabled={!llamaStatus.running}>Остановить</button><button className="btn secondary" onClick={refreshLlama}>Статус/логи</button></div><pre className="llama-log">{llamaLogs||`Статус: ${llamaStatus.running?`работает, PID ${llamaStatus.pid}`:"остановлен"}`}</pre></div>}
 <div className="form-card"><span className="eyebrow">SAMPLING</span><label className="field-label">Temperature <output>{settings.temperature}</output><input type="range" min="0" max="2" step="0.05" value={settings.temperature} onChange={e=>setSetting("temperature",e.target.value)}/></label><label className="field-label">Top P <output>{settings.topP}</output><input type="range" min="0.05" max="1" step="0.05" value={settings.topP} onChange={e=>setSetting("topP",e.target.value)}/></label><label className="field-label">Контекстное окно (Ollama num_ctx)<input type="number" min="256" max="131072" step="256" value={settings.contextTokens} onChange={e=>setSetting("contextTokens",e.target.value)}/></label><label className="field-label">Макс. новых токенов<input type="number" min="1" max="32768" value={settings.maxTokens} onChange={e=>setSetting("maxTokens",e.target.value)}/></label><div className="callout">Неподдерживаемые движком параметры могут игнорироваться. Токены/сек и токены контекста не отображаются без достоверных данных провайдера.</div></div><div className="form-card wide"><span className="eyebrow">ПОДДЕРЖКА В ЭТОМ ZIP</span><p>Реальный запрос к локальному движку через Tauri: Ollama и OpenAI-compatible endpoint. Streaming, LM Studio native API, управление процессом llama.cpp, отмена запроса и обнаружение возможностей отмечены как следующие этапы, не как готовые функции.</p></div></div></SettingsPage>}
 {view==="Theme"&&<SettingsPage title="Внешний вид" eyebrow="PERSONALIZATION" icon={Settings2}><div className="form-grid"><div className="form-card"><span className="eyebrow">COLOR PALETTE</span><p>Выбери акцент интерфейса. Выбор сохраняется локально.</p><div className="swatches">{Object.entries(PALETTES).map(([key,p])=><button key={key} className={`swatch ${settings.theme===key?"chosen":""}`} style={{"--swatch":p.accent}} onClick={()=>setSetting("theme",key)} aria-label={`Палитра ${key}`}><i/>{key}{settings.theme===key&&<Check size={15}/>}</button>)}<label className={`swatch ${settings.theme==="custom"?"chosen":""}`}><i style={{background:settings.customAccent||"#e1c43a"}}/>Свой цвет<input aria-label="Свой цвет акцента" type="color" value={settings.customAccent||"#e1c43a"} onChange={e=>{setSetting("customAccent",e.target.value);setSetting("theme","custom")}}/></label></div><label className="field-label">Шрифт интерфейса<select value={settings.font} onChange={e=>setSetting("font",e.target.value)}><option>Inter</option><option>Segoe UI</option><option>Arial</option><option>Verdana</option><option>Georgia</option><option>system-ui</option></select></label><div className="font-preview" style={{fontFamily:settings.font}}>SYNAPS · Understand. Construct. Control.</div></div><div className="form-card"><span className="eyebrow">APPEARANCE</span><div className="theme-preview"><div/><div/><div/></div><p>Тёмная инженерная палитра. Значения темы применяются сразу и хранятся в настройках проекта.</p><button className="btn secondary" onClick={()=>setSettings(s=>({...s,...DEFAULT}))}>Сбросить настройки</button></div></div></SettingsPage>}
 {view==="Custom Nodes"&&<SettingsPage title="Custom Node Studio" eyebrow="USER NODE MANIFESTS" icon={Code2} action={<button className="btn primary" onClick={()=>setCustomModal(true)}><Plus size={15}/> Новый узел</button>}><div className="callout">Можно собрать и экспортировать metadata/port manifest. Исполнение пользовательского кода и импорт чужих executable packages отключены: sandbox/permission model ещё не готов.</div>{customNodes.length?<div className="skills-grid">{customNodes.map(item=><article className="skill-card" key={item.id}><div className="skill-icon"><Code2 size={17}/></div><span className="eyebrow">{item.category} · v{item.version}</span><h3>{item.name}</h3><p>{item.description}</p><p>Ports: {item.inputs.join(", ")} → {item.outputs.join(", ")}</p><span className="status-pill partial">Manifest only · no handler</span><div className="skill-actions"><button className="btn secondary" onClick={()=>exportCustomNode(item)}><Download size={14}/> Export manifest</button><button className="icon-btn danger" onClick={()=>setCustomNodes(xs=>xs.filter(x=>x.id!==item.id))} aria-label="Удалить пользовательский узел"><Trash2 size={15}/></button></div></article>)}</div>:<div className="empty-skills"><Code2 size={25}/><b>Custom node manifests</b><span>Описания и типы портов хранятся локально; пользовательский код не выполняется.</span><button className="btn secondary" onClick={()=>setCustomModal(true)}><Plus size={14}/> Создать manifest</button></div>}</SettingsPage>}
 {view==="Skills"&&<SettingsPage title="Мои навыки" eyebrow="SKILL STUDIO" icon={Sparkles} action={<button className="btn primary" onClick={()=>setSkillModal(true)}><Plus size={15}/> Создать навык</button>}><div className="skill-info"><Sparkles size={18}/><span>Навык — локально сохранённый манифест с инструкциями, версией и описанием. В этой сборке навыки можно создавать и экспортировать; автоматическое исполнение навыков не включено.</span></div>{skills.length?<div className="skills-grid">{skills.map(s=><article className="skill-card" key={s.id}><div className="skill-icon"><Sparkles size={18}/></div><span className="eyebrow">VERSION {s.version}</span><h3>{s.name}</h3><p>{s.description||"Без описания"}</p><details><summary>Инструкции</summary><pre>{s.instructions}</pre></details><div className="skill-actions"><button className="btn secondary" onClick={()=>exportSkill(s)}><Download size={14}/> Экспорт JSON</button><button className="icon-btn danger" title="Удалить навык" onClick={()=>setSkills(xs=>xs.filter(x=>x.id!==s.id))}><Trash2 size={15}/></button></div></article>)}</div>:<div className="empty-skills"><Sparkles size={25}/><b>Пока нет пользовательских навыков</b><span>Создай инструкцию и сохрани её как переносимый манифест JSON.</span><button className="btn secondary" onClick={()=>setSkillModal(true)}><Plus size={14}/> Создать первый навык</button></div>}</SettingsPage>}
 <footer className="statusbar"><span><i className="green-dot"/>LOCAL PROJECT</span><span>{nodes.length} узлов · {edges.length} соединений</span><span>SYNAPS · FOUNDATION BUILD</span></footer></main>
 {customModal&&<div className="modal-scrim" onMouseDown={e=>{if(e.target===e.currentTarget)setCustomModal(false)}}><div className="modal" onKeyDown={e=>{if(e.key==="Enter"&&e.target.tagName!=="TEXTAREA"){e.preventDefault();createCustomNode()}}}><div className="modal-head"><div><span className="eyebrow">CUSTOM NODE MANIFEST</span><h2>Новый узел</h2></div><button type="button" className="icon-btn" onClick={()=>setCustomModal(false)} aria-label="Закрыть"><X size={17}/></button></div><label className="field-label">Имя<input value={nodeDraft.name} onChange={e=>setNodeDraft(x=>({...x,name:e.target.value}))}/></label><label className="field-label">Описание<input value={nodeDraft.description} onChange={e=>setNodeDraft(x=>({...x,description:e.target.value}))}/></label><label className="field-label">Категория<select value={nodeDraft.category} onChange={e=>setNodeDraft(x=>({...x,category:e.target.value}))}>{["INPUT","MODEL","PROMPT","SAFETY","MEMORY","PROCESSING","TOOL","OUTPUT"].map(c=><option key={c}>{c}</option>)}</select></label><div className="form-grid"><label className="field-label">Тип входа<select value={nodeDraft.inputType} onChange={e=>setNodeDraft(x=>({...x,inputType:e.target.value}))}>{["text","messages","image","audio","document","json","context","number","boolean","memory","tool","signal"].map(t=><option key={t}>{t}</option>)}</select></label><label className="field-label">Тип выхода<select value={nodeDraft.outputType} onChange={e=>setNodeDraft(x=>({...x,outputType:e.target.value}))}>{["text","messages","image","audio","document","json","context","number","boolean","memory","tool","signal"].map(t=><option key={t}>{t}</option>)}</select></label></div><label className="field-label">Версия<input value={nodeDraft.version} onChange={e=>setNodeDraft(x=>({...x,version:e.target.value}))}/></label><label className="field-label">Документация<textarea rows="3" value={nodeDraft.documentation} onChange={e=>setNodeDraft(x=>({...x,documentation:e.target.value}))}/></label><div className="callout">Этот manifest описывает интерфейс узла. Без sandboxed handler узел не исполняется.</div><div className="modal-actions"><button type="button" className="btn secondary" onClick={()=>setCustomModal(false)}>Отмена</button><button type="button" className="btn primary" onClick={createCustomNode}><Save size={14}/> Сохранить</button></div></div></div>}
 {skillModal&&<div className="modal-scrim" onMouseDown={e=>{if(e.target===e.currentTarget)setSkillModal(false)}}><div className="modal" onKeyDown={e=>{if(e.key==="Enter"&&e.target.tagName!=="TEXTAREA"){e.preventDefault();addSkill()}}}><div className="modal-head"><div><span className="eyebrow">SKILL MANIFEST</span><h2>Создать навык</h2></div><button type="button" className="icon-btn" aria-label="Закрыть" onClick={()=>setSkillModal(false)}><X size={17}/></button></div><label className="field-label">Название<input value={newSkill.name} onChange={e=>setNewSkill(s=>({...s,name:e.target.value}))} placeholder="Например, Редактор кода"/></label><label className="field-label">Описание<input value={newSkill.description} onChange={e=>setNewSkill(s=>({...s,description:e.target.value}))} placeholder="Для чего этот навык"/></label><label className="field-label">Версия<input value={newSkill.version} onChange={e=>setNewSkill(s=>({...s,version:e.target.value}))}/></label><label className="field-label">Инструкции<textarea rows="7" value={newSkill.instructions} onChange={e=>setNewSkill(s=>({...s,instructions:e.target.value}))} placeholder="Явные инструкции, которые будут сохранены в манифесте..."/></label><div className="callout">Инструкции сохраняются как данные и не исполняются автоматически.</div><div className="modal-actions"><button type="button" className="btn secondary" onClick={()=>setSkillModal(false)}>Отмена</button><button type="button" className="btn primary" onClick={addSkill}><Save size={15}/> Сохранить навык</button></div></div></div>}
 {status&&<div className="toast"><Check size={15}/>{status}</div>}</div>
}
function SettingsPage({title,eyebrow,icon:Icon,action,children}){return <section className="settings-page"><header className="settings-heading"><span className="settings-icon"><Icon size={20}/></span><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1></div>{action&&<div className="heading-action">{action}</div>}</header><div className="settings-content">{children}</div></section>}
